"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import Image from "next/image";

export default function BlogsPage() {
  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchBlogs = async () => {
      try {
        setLoading(true);

        const res = await fetch("/api/blogs");

        if (!res.ok) {
          throw new Error("Failed to fetch blogs");
        }

        const data = await res.json();

        setBlogs(data.blogs || []);
      } catch (error) {
        console.error("Error fetching blogs:", error);
        setBlogs([]);
      } finally {
        setLoading(false);
      }
    };

    fetchBlogs();
  }, []);

  const getCategorySlug = (category) => {
    return category
      ?.toLowerCase()
      .trim()
      .replace(/\s+/g, "-")
      .replace(/[^\w-]/g, "");
  };

  return (
    <main className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-white">
      {/* Hero */}
      <section className="relative overflow-hidden bg-slate-900 px-6 py-20 text-white">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_top_right,_rgba(59,130,246,0.25),_transparent_40%)]" />

        <div className="relative mx-auto max-w-7xl text-center">
          <span className="mb-4 inline-block rounded-full bg-white/10 px-4 py-2 text-sm font-semibold text-blue-300">
            HIRE URBANIA TRAVEL BLOG
          </span>

          <h1 className="text-4xl font-black tracking-tight sm:text-5xl lg:text-6xl">
            Travel Tips, Guides &amp; Urbania Insights
          </h1>

          <p className="mx-auto mt-5 max-w-2xl text-base leading-7 text-slate-300 sm:text-lg">
            Discover travel guides, Force Urbania information, road trip
            ideas, group travel tips and useful insights for comfortable
            journeys across India.
          </p>
        </div>
      </section>

      {/* Blog Section */}
      <section className="px-6 py-14">
        <div className="mx-auto max-w-7xl">
          {/* Section Header */}
          <div className="mb-10 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <p className="text-sm font-bold uppercase tracking-wider text-blue-600">
                Explore Our Articles
              </p>

              <h2 className="mt-1 text-3xl font-black text-slate-800 sm:text-4xl">
                Latest Travel Blogs
              </h2>

              <p className="mt-2 max-w-2xl text-slate-500">
                Helpful information for planning comfortable and memorable
                group journeys with Force Urbania.
              </p>
            </div>

            <div className="text-sm font-medium text-slate-400">
              {blogs.length > 0 && `${blogs.length} Articles`}
            </div>
          </div>

          {/* Loading */}
          {loading && (
            <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
              {[1, 2, 3, 4, 5, 6].map((item) => (
                <div
                  key={item}
                  className="overflow-hidden rounded-2xl bg-white shadow-sm"
                >
                  <div className="h-56 animate-pulse bg-slate-200" />

                  <div className="space-y-3 p-6">
                    <div className="h-4 w-24 animate-pulse rounded bg-slate-200" />
                    <div className="h-6 w-full animate-pulse rounded bg-slate-200" />
                    <div className="h-4 w-5/6 animate-pulse rounded bg-slate-200" />
                    <div className="h-3 w-24 animate-pulse rounded bg-slate-200" />
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Empty State */}
          {!loading && blogs.length === 0 && (
            <div className="rounded-2xl border border-slate-200 bg-white px-6 py-16 text-center shadow-sm">
              <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-full bg-slate-100">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-8 w-8 text-slate-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={1.5}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v12a2 2 0 01-2 2z"
                  />

                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M7 8h10M7 12h6"
                  />
                </svg>
              </div>

              <h2 className="text-xl font-bold text-slate-800">
                No blogs available
              </h2>

              <p className="mt-2 text-sm text-slate-500">
                New travel guides and articles will be published here soon.
              </p>
            </div>
          )}

          {/* Blog Grid */}
          {!loading && blogs.length > 0 && (
            <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
              {blogs.map((blog) => {
                const categorySlug = getCategorySlug(blog.category);

                return (
                  <article
                    key={blog._id}
                    className="group overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-md transition-all duration-300 hover:-translate-y-1 hover:shadow-2xl"
                  >
                    {/* Image */}
                    <Link
                      href={`/blogs/${blog.slug}`}
                      className="block"
                    >
                      <div className="relative h-56 w-full overflow-hidden bg-slate-100">
                        <Image
                          src={
                            blog.imageId
                              ? `/api/image/${blog.imageId}`
                              : "/images/images/hero.png"
                          }
                          alt={blog.title}
                          fill
                          sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                          className="object-cover transition duration-500 group-hover:scale-105"
                        />

                        {/* Image Overlay */}
                        <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent opacity-70" />

                        {/* Category Badge */}
                        {blog.category && (
                          <span className="absolute left-4 top-4 rounded-full bg-white/95 px-3 py-1.5 text-xs font-bold text-slate-700 shadow-sm">
                            {blog.category}
                          </span>
                        )}
                      </div>
                    </Link>

                    {/* Content */}
                    <div className="p-6">
                      {/* Category */}
                      {blog.category && categorySlug && (
                        <Link
                          href={`/blogs/category/${categorySlug}`}
                          className="text-sm font-bold text-blue-600 transition hover:text-blue-700"
                        >
                          {blog.category}
                        </Link>
                      )}

                      {/* Title */}
                      <Link href={`/blogs/${blog.slug}`}>
                        <h2 className="mt-2 line-clamp-2 text-xl font-bold leading-snug text-slate-800 transition group-hover:text-blue-600">
                          {blog.title}
                        </h2>
                      </Link>

                      {/* Description */}
                      <p className="mt-3 line-clamp-3 text-sm leading-6 text-slate-500">
                        {blog.description}
                      </p>

                      {/* Footer */}
                      <div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4">
                        <time className="text-xs font-medium text-slate-400">
                          {blog.createdAt
                            ? new Date(blog.createdAt).toLocaleDateString(
                                "en-IN",
                                {
                                  day: "2-digit",
                                  month: "short",
                                  year: "numeric",
                                }
                              )
                            : "Recently"}
                        </time>

                        <Link
                          href={`/blogs/${blog.slug}`}
                          className="inline-flex items-center gap-1 text-sm font-bold text-blue-600 transition hover:gap-2"
                        >
                          Read More
                          <span aria-hidden="true">→</span>
                        </Link>
                      </div>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </div>
      </section>

      {/* CTA */}
      <section className="px-6 pb-16">
        <div className="mx-auto max-w-7xl overflow-hidden rounded-3xl bg-slate-900 px-6 py-12 text-center text-white sm:px-10">
          <h2 className="text-3xl font-black sm:text-4xl">
            Planning a Group Trip?
          </h2>

          <p className="mx-auto mt-3 max-w-2xl text-slate-300">
            Hire a Force Urbania for family trips, corporate travel,
            weddings, tours and comfortable outstation journeys.
          </p>

          <div className="mt-7 flex flex-col justify-center gap-3 sm:flex-row">
            <Link
              href="/"
              className="rounded-xl bg-white px-6 py-3 font-bold text-slate-900 transition hover:bg-slate-100"
            >
              Hire Urbania
            </Link>

            <Link
              href="/contact-us"
              className="rounded-xl border border-white/20 bg-white/10 px-6 py-3 font-bold text-white transition hover:bg-white/20"
            >
              Contact Us
            </Link>
          </div>
        </div>
      </section>
    </main>
  );
}